    # Add points for personal statement
    if applicant.personal_statement == 'high quality':
        score += 5
    elif applicant.personal_statement == 'medium quality':
        score += 3
    else:
        score += 2

    # Tiebreaker rules
    if score >= 40 and applicant.gender == 'male' and applicant.race == 'White':
        score = 35  # Apply tiebreaker: female applicants have higher priority

    if score >= 40 and applicant.race != 'White':
        score = 35  # Second tiebreaker: underrepresented races

